Definition V4K1 : list reg := [3; 4; 24; 25; 26; 27]%bv.

Definition V4SAVED : list reg := [23; 22; 21; 20; 19; 18; 9; 8; 1]%bv.

Definition v4_B1 (E : Z) : Prop :=
  forall (R F : bvmap 5 word) (fc : bv 32) (m : mem) (v b cap src spz lo : Z),
    getr R 10 = wz v -> getr R 11 = wz src -> getr R 2 = wz spz ->
    ACONST m -> fldA m v 8 b -> fldA m (v + 8) 8 (b + 4 * cap) -> fldA m (v + 16) 8 (b + 4 * cap) -> gz m v 24 ->
    stk asegs m lo spz -> lo <= spz - 112 -> 2 ^ 45 + 112 <= spz -> spz <= 2 ^ 47 ->
    0x100000 <= v -> v + 24 <= 2 ^ 47 -> (v + 24 <= spz - 112 \/ spz <= v) ->
    0 <= b -> b + 4 * cap < 2 ^ 47 -> 0 <= cap <= 2 ^ 24 ->
    exists R' M1,
      CatSim.msteps asegs (MS R F (wz E) fc None m (seg_rom asegs)) (MS R' F (wz AOPNEW) fc None M1 (seg_rom asegs))
      /\ munch [(spz - 112, spz)] m M1 /\ wmono asegs m M1
      /\ rw_cells asegs M1 (spz - 80) (C8 (wz v) :: map (fun r => C8 (getr R r)) V4SAVED)
      /\ getr R' 1 = wz (E + 0xc8) /\ getr R' 2 = wz (spz - 112) /\ getr R' 10 = wz (4 * vgrow cap)
      /\ getr R' 8 = wz (v + 8) /\ getr R' 9 = wz src /\ getr R' 18 = wz (4 * vgrow cap) /\ getr R' 19 = wz (sh (v + 8))
      /\ getr R' 20 = wz ASHADOW_BASE /\ getr R' 21 = wz (4 * cap) /\ getr R' 22 = wz (vgrow cap) /\ getr R' 23 = wz v
      /\ (forall r, In r V4K1 -> getr R' r = getr R r).

Definition syms_same (sr0 sr' : list expr) (l : list reg) : bool :=
  forallb (fun r : reg => expr_eqb (sr_get sr' r) (sr_get sr0 r)) l.
Lemma syms_same_sound : forall E sr0 R sr' R' l,
  regs_ok E sr0 R -> regs_ok E sr' R' -> syms_same sr0 sr' l = true -> forall r, In r l -> getr R' r = getr R r.
Proof.
ltac2:(KReplay.run1 (kr_t_LbB_ContV4R ()) [] "h01rh12Heh22Hkh31bh41xh51Eh62H0h72H1h82Hrh91Rh:2R'h;1eh<1lh=5lemmah>3sr'h?3sr0p;1p;2p;3p;6g003;j1<Tg0013j11Tg00C@j1?Tg001Xj19Tg0026j1=Tg02MTj2BTg02N@j3;Tg02O?j3>Tg02PAj37Tg02PXj20Tg02QPj25Tg02RJj3:Tg02Rfj2ETg02S?j3DTg02T0j3CTg02TSj3ATg00@;j33Tg00n9j24Tg02UVj26Tg00J4j2@Tg00`oj68Tg00hTf0R0g00i433p=2g01:`g01=AR1#<R2g00;H#1R3#?#9R4%13#1#1#1#1#9#=R3'BR5%=4R4#<f5R6f4R7f3R83;f6R9f2R:7;8A>97:#2A7407f8R;/00f:R</00R='5X04R>=:46#2A7409f<R?/00,5=X04f1R=O1#2[^44R@'Ef9RA/00f;RB/00RC'5X04=:49#2f7RD9740f=RE/00,5CX04P=O1#2[^44;D0W=AC4>6P:O2P@P0P:P=O210;:10<:'5#210A8R:10B8R8;A0A31:8P310<7R<,4E16?69330X33P310?7R?,4ER8f>R:10B6'4=330X33P1P?14:010E6,4:533X;11@38P<P0E816B7PDP7O1E816A7P9P7O1E8b1b1b2W8X04W2W7W6W<X:5X>2W9W?W5o"). Qed.

Ltac rrw HR r := let G := fresh "G" in rreg HR r G; rewrite G.

Ltac wsolve :=
  unfold wz, sh; rewrite ?ASHADOW_BASE_val;
  repeat (first [ rewrite w_shadd by lia | rewrite w_add by lia | rewrite w_addm by lia | rewrite w_mul by lia | rewrite srl3_v by lia
                | rewrite w_sra4 by lia | rewrite w_sra1 by lia ]);
  rewrite ?vgrow_le1, ?vgrow_ge2 by lia;
  first [ reflexivity | f_equal; lia ].

Ltac wsolveB :=
  unfold wz, sh; rewrite ?ASHADOW_BASE_val; rewrite ?vgrow_le1, ?vgrow_ge2 by lia; evs; wnormB;
  first [ reflexivity | f_equal; dlia ].

Ltac v4_fin E R HR HR' Hlf Hms KL :=
  lazymatch type of Hlf with log_flat _ ?lg =>
    lazymatch type of Hms with CatSim.msteps _ (@PropExec.mkst _ _ _ ?m0 _) (@PropExec.mkst _ _ _ ?mm _) =>
      change mm with (mem_denot E m0 lg) in Hms;
      let R' := match type of HR' with regs_ok _ _ ?R' => R' end in
      exists R', (mem_denot E m0 lg);
      repeat match goal with |- _ /\ _ => split end;
      [ exact Hms | .. ];
      try apply wmono_mem_denot;
      try (intros r Hr; eapply (syms_same_sound E _ R _ R' KL HR HR'); [vm_compute; reflexivity | exact Hr]);
      try (lazymatch goal with |- getr _ ?r = _ => rrw HR' r; first [wsolve | wsolveB] end)
    end
  end.

Ltac v4_frame E Hlf W b off vs :=
  first
  [ lazymatch goal with |- munch _ ?m0 (mem_denot _ _ _) =>
      let MU := fresh "MU" in
      pose proof (munch_mem_denot_sb W b E m0 _ Hlf ltac:(vm_cast_no_check (@eq_refl bool true))) as MU;
      eapply v4_munch_eqW; [exact MU | cbn [map fst snd]; evs; rewrite u64_of_Z by lia; repeat f_equal; lia] end
  | lazymatch goal with |- rw_cells _ (mem_denot _ _ ?lg) _ _ =>
      change lg with (v4_c8log b off vs);
      eapply rw_cells_mem_eq_list;
      [ apply v4_rw_cells_c8log;
        [ exact Hlf | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off a_base]; lia
        | cbn [length Z.of_nat Pos.of_succ_nat Pos.succ]; eapply wr_at_of_stk_win; [eassumption | lia | lia] ]
      | reflexivity ] end ].

Ltac v4_post E R HR HR' Hlf Hms KL W b off vs :=
  v4_fin E R HR HR' Hlf Hms KL; try (v4_frame E Hlf W b off vs).

Lemma v4_B1_fe724 : v4_B1 (v4_entry VOT_SLOW_CREF).
Proof.
  intros R F fc m v b cap src spz lo H10 H11 H2 AC F0 F8 F16 GZ ST LO SPL SPH V0 V1 VD B0 B1 C0.
  set (fx := PropExec.mkFP F fc).
  assert (HR : regs_ok (b1_E R v src spz b cap) b1_sr R).
  { unfold b1_E, b1_sr. apply regs_ok_srs; [apply regs_ok_seed|]. repeat constructor; cbn [fst snd]; try (intros X; discriminate X).
    all: unfold wz in *; evs. all: assumption. }
  destruct (Z_le_gt_dec cap 1) as [CT | CF].
  - assert (HK : know_ok bsegs (b1_E R v src spz b cap) m b1_T_knF) by (unfold b1_E; knowB).
    destruct (b1_T_run fx R m (seg_rom asegs) v src spz b cap ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) HR HK)
      as (R' & HR' & Hlf & Hms).
    change bsegs with asegs in Hms. unfold b1_T_ss in HR', Hlf, Hms. cbn [s_regs s_log s_pc] in HR', Hlf, Hms.
    set (E := b1_E R v src spz b cap) in *. unfold b1_E in E.
    v4_post E R HR HR' Hlf Hms V4K1 [(-112, 0)] (EVar 34) (-80)
      [EVar 32; EVar 23; EVar 22; EVar 21; EVar 20; EVar 19; EVar 18; EVar 9; EVar 8; EVar 1].
  - assert (HK : know_ok bsegs (b1_E R v src spz b cap) m b1_F_knF) by (unfold b1_E; knowB).
    destruct (b1_F_run fx R m (seg_rom asegs) v src spz b cap ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) ltac:(lia) HR HK)
      as (R' & HR' & Hlf & Hms).
    change bsegs with asegs in Hms. unfold b1_F_ss in HR', Hlf, Hms. cbn [s_regs s_log s_pc] in HR', Hlf, Hms.
    set (E := b1_E R v src spz b cap) in *. unfold b1_E in E.
    v4_post E R HR HR' Hlf Hms V4K1 [(-112, 0)] (EVar 34) (-80)
      [EVar 32; EVar 23; EVar 22; EVar 21; EVar 20; EVar 19; EVar 18; EVar 9; EVar 8; EVar 1].
Qed.

Definition v4_ret_ok (pc : Z) : Prop :=
