Definition v4_at (ss : sym_state) (pc ra : Z) : sym_state := SS pc (sr_upd (s_regs ss) 1 (ELit ra)) (s_log ss) (s_know ss) (s_next ss).
Definition v4_pcat (ss : sym_state) (pc : Z) : sym_state := SS pc (s_regs ss) (s_log ss) (s_know ss) (s_next ss).

Ltac v4_run FX EQ HR HK HS ss0 :=
  let R' := fresh "R'" in let HR' := fresh "HR'" in let Hlf := fresh "Hlf" in let Hms := fresh "Hms" in
  destruct (@SymRun3.run_sound FX asegs _ _ _ _ _ _ _ _ _ _ _ _ (seg_rom asegs) _ EQ HR HK HS) as (R' & HR' & Hlf & Hms);
  unfold v4_at, v4_pcat in HR', Hlf, Hms; unfold ss0 in HR', Hlf, Hms; cbn [s_regs s_log s_pc] in HR', Hlf, Hms.

Ltac vmeq := lazymatch goal with |- _ = ?r => vm_cast_no_check (@eq_refl _ r) end.

Definition v4_shx (e : expr) : expr := EAlu ALU_ADD (EAlu ALU_SRL e (ELit 3)) (ELit 0x7fff8000).

Ltac v4_seed :=
  apply regs_ok_srs; [apply regs_ok_seed|];
  repeat (apply Forall_cons; [cbn [fst snd]; split; [intros X; discriminate X|];
            match goal with H : getr ?R ?r = _ |- getr ?R ?r = _ => rewrite H end; evs; wsolve |]);
  apply Forall_nil.

Ltac v4_sc3 :=
  cbn [sc_denot]; unfold SymExec3Sound.SX2S.flat, estart, elenZ; cbn [a_base a_off]; evs; unfold wz;
  repeat (first [rewrite w_shadd by lia | rewrite w_add by lia | rewrite w_mul by lia | rewrite srl3_v by lia]);
  rewrite ?u64_of_Z by lia;
  first [ lia
        | rewrite ?land7_val by lia; rewrite ?w_add by lia; rewrite br_lts_small by lia; bool_lia ].

Ltac v4_kentry E m :=
  first [ match goal with Hf : fldA _ ?p ?k _ |- kentry_ok _ _ _ (KWord _ ?k _) =>
            eapply (kword_of_fldA E m _ _ k p); [exact Hf | lia | unfold estart; evs; rewrite u64_of_Z by lia; cbn [a_off]; lia | lia | cbn; lia
                                                 | evs; unfold wz; rewrite ?w_mul, ?w_add by lia; reflexivity] end
        | match goal with Hs : shk _ ?p ?kv |- kentry_ok _ _ _ (KWord (SA (EAlu ALU_SRL ?e (ELit 3)) _) 1 _) =>
            eapply (kshadow E m e p kv); [evs; reflexivity | lia | lia | evs; reflexivity | exact Hs] end
        | match goal with Hw : wr_at _ _ ?A ?n |- kentry_ok _ _ _ (KWr _ _) =>
            eapply (kwr_of_wr_at _ E m A n); [exact Hw | unfold estart; evs; unfold wz; rewrite ?w_mul, ?w_add by lia; rewrite u64_of_Z by lia; cbn [a_off]; lia
                                   | unfold estart, elenZ; evs; unfold wz; rewrite ?w_mul, ?w_add by lia; rewrite !u64_of_Z by lia; cbn [a_off]; lia
                                   | unfold elenZ; evs; rewrite u64_of_Z by lia; lia] end
        | cbn [kentry_ok]; evs; rewrite u64_of_Z by lia; first [lia | split; [lia | Z.div_mod_to_equations; lia]]
        | kentry_tac ].
Ltac v4_kn3_tac E m :=
  kn_eval; unfold know_ok;
  repeat (apply Forall_cons; [ v4_kentry E m |]);
  apply Forall_nil.
